def render(rows): return "\n".join(json.dumps(x,sort_keys=True,separators=(",",":"),ensure_ascii=False) for x in rows)+"\n"
def main():
 ROOT.mkdir(parents=True,exist_ok=True); files={}
 for name,rows in FILES.items():
  payload=render(rows); (ROOT/name).write_text(payload,encoding="utf-8"); files[name]={"records":len(rows),"sha256":hashlib.sha256(payload.encode()).hexdigest()}
 schema_payload=json.dumps(CONTROL_SCHEMA,indent=2,sort_keys=True)+"\n"; (ROOT/"corpus-control.schema.json").write_text(schema_payload); files["corpus-control.schema.json"]={"sha256":hashlib.sha256(schema_payload.encode()).hexdigest()}
 (ROOT/"manifest.json").write_text(json.dumps({"manifest_id":"experiment_integrity_analysis_conclusion_v0_1_0","as_of":AS_OF,"edition":1,"status":"specified_unimplemented_open_world","files":files,"completion_claim":False,"qualified_implementation_count":0},indent=2,sort_keys=True)+"\n")
 print(f"BUILD PASS eiac: {len(SOURCES)} sources, {len(CONTEXTS)} contexts, {len(DECISION_ROWS)} decisions, {len(LIBRARIES)} libraries, {sum(len(v) for v in OPS.values())} operations, {len(LENS_ROWS)} lenses, {len(NEGATIVE_ROWS)} negative twins")
if __name__=="__main__": main()
